// ParseArgusRpcIds converts a comma-separated string to a slice of ArgusRpcId enum values
// Returns an error if any value is invalid
func ParseArgusRpcIds(s string) ([]ArgusRpcId, error) {
	if s == "" {
		return nil, nil
	}
	parts := strings.Split(s, ",")
	result := make([]ArgusRpcId, 0, len(parts))
	for _, part := range parts {
		trimmed := strings.TrimSpace(part)
		if trimmed == "" {
			continue
		}
		val, err := ParseArgusRpcId(trimmed)
		if err != nil {
			return nil, err
		}
		result = append(result, val)
	}
	return result, nil
}

